initJs:
function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const STORES_TABLE = 1;
  const PRODUCTS_TABLE = 2;
  const PREDICTION_RESULTS_TABLE = 10;
  const WEATHER_DATA_TABLE = 4;
  const EVENT_DATA_TABLE = 5;

  // 予測結果再描画関数
  function renderPredictionResults(results) {
    const tbody = container.querySelector("#prediction-results-tbody");
    if (!results || results.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" style="text-align: center; color: var(--text-muted); padding: 40px;">予測結果がありません</td></tr>';
      return;
    }

    tbody.innerHTML = results.map(r => `
      <tr data-id="${r.id}">
        <td>${r.store_name || ""}</td>
        <td>${r.product_name || ""}</td>
        <td>${r.prediction_date ? new Date(r.prediction_date).toLocaleDateString() : ""}</td>
        <td>${r.predicted_quantity || 0}</td>
        <td>${r.prediction_accuracy ? (r.prediction_accuracy + "%") : ""}</td>
        <td>${r.recommended_order_quantity || 0}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 4px; font-size: 12px; 
            ${r.prediction_status === '完了' ? 'background: rgba(34, 197, 94, 0.1); color: #22c55e; border: 1px solid #22c55e;' : 
              r.prediction_status === '算出中' ? 'background: rgba(251, 191, 36, 0.1); color: #fbbf24; border: 1px solid #fbbf24;' : 
              'background: rgba(239, 68, 68, 0.1); color: #ef4444; border: 1px solid #ef4444;'}">
            ${r.prediction_status || "未実行"}
          </span>
        </td>
      </tr>
    `).join("");
  }

  // 店舗データ読み込み
  async function loadStores() {
    const stores = await window.aivicApi.list(STORES_TABLE);
    const storeSelect = container.querySelector("#store-select");
    if (stores) {
      storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' + 
        stores.filter(s => s.active_flag).map(s => `<option value="${s.id}">${s.store_name}</option>`).join("");
    }
  }

  // 商品カテゴリ読み込み
  async function loadCategories() {
    const products = await window.aivicApi.list(PRODUCTS_TABLE);
    const categoryList = container.querySelector("#category-list");
    if (products) {
      const categories = [...new Set(products.map(p => p.product_category_id).filter(Boolean))];
      categoryList.innerHTML = categories.map(cat => 
        `<label style="display: block; margin-bottom: 5px; color: var(--text);">
          <input type="checkbox" class="category-checkbox" value="${cat}" style="margin-right: 8px;"> カテゴリ${cat}
        </label>`
      ).join("");
    }
  }

  // 初期データ読み込み
  async function loadInitialData() {
    await loadStores();
    await loadCategories();

    // 予測結果の初期表示
    const predictionResults = await window.aivicApi.list(PREDICTION_RESULTS_TABLE);
    if (predictionResults) {
      // 店舗名と商品名を結合
      const stores = await window.aivicApi.list(STORES_TABLE);
      const products = await window.aivicApi.list(PRODUCTS_TABLE);

      const enrichedResults = predictionResults.map(result => ({
        ...result,
        store_name: stores?.find(s => s.id === result.store_id)?.store_name || "",
        product_name: products?.find(p => p.id === result.product_id)?.product_name || ""
      }));

      renderPredictionResults(enrichedResults);
    }
  }

  // 季節要因スライダー
  const seasonalSlider = container.querySelector("#seasonal-factor");
  const seasonalValue = container.querySelector("#seasonal-value");
  seasonalSlider.addEventListener("input", () => {
    seasonalValue.textContent = seasonalSlider.value + "%";
  });

  // 全選択チェックボックス
  container.querySelector("#select-all-categories").addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".category-checkbox");
    checkboxes.forEach(cb => cb.checked = e.target.checked);
  });

  // バリデーション関数
  function validateForm() {
    const errors = [];

    const startDate = container.querySelector("#prediction-start-date").value;
    const endDate = container.querySelector("#prediction-end-date").value;
    const stores = Array.from(container.querySelectorAll("#store-select option:checked")).map(o => o.value).filter(v => v);
    const categories = Array.from(container.querySelectorAll(".category-checkbox:checked")).map(cb => cb.value);
    const model = container.querySelector("input[name='prediction-model']:checked");
    const learningStart = container.querySelector("#learning-start-date").value;
    const learningEnd = container.querySelector("#learning-end-date").value;

    if (!startDate || !endDate) {
      errors.push("予測期間を選択してください");
    } else {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (start < today || end < today) {
        errors.push("予測期間に過去の日付は指定できません");
      }

      const diffTime = Math.abs(end - start);
      const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));
      if (diffDays > 365) {
        errors.push("予測期間は1年以内で設定してください");
      }
    }

    if (stores.length === 0) {
      errors.push("店舗を選択してください");
    }

    if (categories.length === 0) {
      errors.push("商品カテゴリを選択してください");
    }

    if (!model) {
      errors.push("予測モデルを選択してください");
    }

    if (!learningStart || !learningEnd) {
      errors.push("学習データ期間の開始日と終了日を入力してください");
    } else if (learningStart && learningEnd && startDate && endDate) {
      const learningStartDate = new Date(learningStart);
      const learningEndDate = new Date(learningEnd);
      const predictionStartDate = new Date(startDate);
      const predictionEndDate = new Date(endDate);

      const learningDays = Math.ceil((learningEndDate - learningStartDate) / (1000 * 60 * 60 * 24));
      const predictionDays = Math.ceil((predictionEndDate - predictionStartDate) / (1000 * 60 * 60 * 24));

      if (learningDays < predictionDays) {
        errors.push("学習データ期間は予測期間以上に設定してください");
      }
    }

    return errors;
  }

  // 進捗バー制御
  function showProgress() {
    const progressContainer = container.querySelector("#progress-container");
    const progressBar = container.querySelector("#progress-bar");
    const progressText = container.querySelector("#progress-text");
    const progressPercentage = container.querySelector("#progress-percentage");
    const executeBtn = container.querySelector("#btn-execute-prediction");

    progressContainer.classList.remove("hidden");
    executeBtn.disabled = true;
    executeBtn.textContent = "処理中...";

    let progress = 0;
    const steps = [
      "データ収集中...",
      "天候データ取得中...",
      "イベントデータ取得中...",
      "学習データ準備中...",
      "AIモデル学習中...",
      "需要予測実行中...",
      "結果生成中...",
      "完了"
    ];

    const interval = setInterval(() => {
      progress += Math.random() * 15 + 5;
      if (progress > 100) progress = 100;

      progressBar.style.width = progress + "%";
      progressPercentage.textContent = Math.round(progress) + "%";

      const stepIndex = Math.floor((progress / 100) * (steps.length - 1));
      progressText.textContent = steps[stepIndex];

      if (progress >= 100) {
        clearInterval(interval);
        setTimeout(() => {
          progressContainer.classList.add("hidden");
          executeBtn.disabled = false;
          executeBtn.textContent = "AI予測実行";
          progressBar.style.width = "0%";
          progressPercentage.textContent = "0%";
          progressText.textContent = "予測処理を実行中...";
        }, 1000);
      }
    }, 200);

    return interval;
  }

  // AI予測実行
  container.querySelector("#btn-execute-prediction").addEventListener("click", async () => {
    const errors = validateForm();
    if (errors.length > 0) {
      alert(errors.join("\n"));
      return;
    }

    const progressInterval = showProgress();

    try {
      // 予測設定データ収集
      const predictionData = {
        start_date: container.querySelector("#prediction-start-date").value,
        end_date: container.querySelector("#prediction-end-date").value,
        store_ids: Array.from(container.querySelectorAll("#store-select option:checked")).map(o => o.value).filter(v => v),
        categories: Array.from(container.querySelectorAll(".category-checkbox:checked")).map(cb => cb.value),
        model: container.querySelector("input[name='prediction-model']:checked").value,
        learning_start: container.querySelector("#learning-start-date").value,
        learning_end: container.querySelector("#learning-end-date").value,
        seasonal_factor: parseInt(container.querySelector("#seasonal-factor").value),
        accuracy_threshold: parseFloat(container.querySelector("#accuracy-threshold").value)
      };

      // 模擬的な予測結果生成
      const stores = await window.aivicApi.list(STORES_TABLE);
      const products = await window.aivicApi.list(PRODUCTS_TABLE);

      if (!stores || !products) {
        throw new Error("店舗または商品データの取得に失敗しました");
      }

      const results = [];
      const selectedStores = stores.filter(s => predictionData.store_ids.includes(s.id));
      const selectedProducts = products.filter(p => predictionData.categories.includes(p.product_category_id));

      for (const store of selectedStores) {
        for (const product of selectedProducts) {
          const result = await window.aivicApi.save(PREDICTION_RESULTS_TABLE, {
            store_id: store.id,
            product_id: product.id,
            prediction_date: predictionData.start_date,
            predicted_quantity: Math.floor(Math.random() * 100) + 10,
            prediction_accuracy: Math.floor(Math.random() * 30) + 70,
            recommended_order_quantity: Math.floor(Math.random() * 80) + 15,
            prediction_model_version: predictionData.model + "_v1.0",
            prediction_status: "完了",
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString()
          });

          if (result) {
            results.push({
              ...result,
              store_name: store.store_name,
              product_name: product.product_name
            });
          }
        }
      }

      // 結果表示
      setTimeout(() => {
        renderPredictionResults(results);
        alert("AI需要予測処理が完了しました。" + results.length + "件の予測結果を生成しました。");
      }, 2000);

    } catch (error) {
      clearInterval(progressInterval);
      container.querySelector("#progress-container").classList.add("hidden");
      container.querySelector("#btn-execute-prediction").disabled = false;
      container.querySelector("#btn-execute-prediction").textContent = "AI予測実行";
      alert("AI予測実行に失敗しました: " + error.message);
    }
  });

  // 天候データ取込
  container.querySelector("#btn-import-weather").addEventListener("click", async () => {
    try {
      const startDate = container.querySelector("#prediction-start-date").value;
      const endDate = container.querySelector("#prediction-end-date").value;

      if (!startDate || !endDate) {
        alert("予測期間を設定してから天候データを取り込んでください");
        return;
      }

      // 模擬的な天候データ生成
      const stores = await window.aivicApi.list(STORES_TABLE);
      if (!stores) {
        throw new Error("店舗データの取得に失敗しました");
      }

      let importCount = 0;
      const start = new Date(startDate);
      const end = new Date(endDate);

      for (let d = new Date(start); d <= end; d.setDate(d.getDate() + 1)) {
        for (const store of stores.slice(0, 3)) { // 最初の3店舗のみ
          const weatherData = await window.aivicApi.save(WEATHER_DATA_TABLE, {
            store_id: store.id,
            observation_date: d.toISOString().split('T')[0],
            weather: ["晴れ", "曇り", "雨", "雪"][Math.floor(Math.random() * 4)],
            max_temperature: Math.floor(Math.random() * 20) + 10,
            min_temperature: Math.floor(Math.random() * 15) + 5,
            avg_temperature: Math.floor(Math.random() * 18) + 8,
            precipitation: Math.floor(Math.random() * 50),
            humidity: Math.floor(Math.random() * 40) + 40,
            wind_speed: Math.floor(Math.random() * 10) + 1,
            data_type: "予報値",
            data_source: "気象庁API",
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString()
          });

          if (weatherData) importCount++;
        }
      }

      alert("天候データの取込が完了しました。" + importCount + "件のデータを取り込みました。");

    } catch (error) {
      alert("天候データの取得に失敗しました。データソースの設定を確認してください。");
    }
  });

  // イベントデータ取込
  container.querySelector("#btn-import-events").addEventListener("click", async () => {
    try {
      const stores = await window.aivicApi.list(STORES_TABLE);
      if (!stores) {
        throw new Error("店舗データの取得に失敗しました");
      }

      const events = [
        { name: "夏祭り", type: "祭り", impact: "大" },
        { name: "コンサート", type: "コンサート", impact: "中" },
        { name: "スポーツ大会", type: "スポーツ", impact: "小" }
      ];

      let importCount = 0;
      for (const store of stores.slice(0, 2)) {
        for (const event of events) {
          const eventData = await window.aivicApi.save(EVENT_DATA_TABLE, {
            store_id: store.id,
            event_name: event.name,
            event_type: event.type,
            start_datetime: new Date(Date.now() + Math.random() * 30 * 24 * 60 * 60 * 1000).toISOString(),
            end_datetime: new Date(Date.now() + Math.random() * 30 * 24 * 60 * 60 * 1000 + 24 * 60 * 60 * 1000).toISOString(),
            expected_visitors: Math.floor(Math.random() * 10000) + 1000,
            impact_level: event.impact,
            location: "地域イベント会場",
            distance_from_store: Math.floor(Math.random() * 5000) + 100,
            active_flag: true,
            created_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
            created_by: "システム自動取得",
            updated_by: "システム自動取得"
          });

          if (eventData) importCount++;
        }
      }

      alert("イベントデータの取込が完了しました。" + importCount + "件のデータを取り込みました。");

    } catch (error) {
      alert("イベントデータの取込に失敗しました。ファイル形式を確認してください。");
    }
  });

  // 初期化
  loadInitialData();

  // デフォルト日付設定
  const today = new Date();
  const tomorrow = new Date(today);
  tomorrow.setDate(tomorrow.getDate() + 1);
  const nextWeek = new Date(today);
  nextWeek.setDate(nextWeek.getDate() + 7);
  const lastMonth = new Date(today);
  lastMonth.setMonth(lastMonth.getMonth() - 1);

  container.querySelector("#prediction-start-date").value = tomorrow.toISOString().split('T')[0];
  container.querySelector("#prediction-end-date").value = nextWeek.toISOString().split('T')[0];
  container.querySelector("#learning-start-date").value = lastMonth.toISOString().split('T')[0];
  container.querySelector("#learning-end-date").value = today.toISOString().split('T')[0];
}
